import { Effect } from "effect";
import { SqlClient } from "effect/sql";
// How many times answering an answer has started (docs/features/chat.md#messages-postgres). Each streaming attempt
// takes the next number and resets the answer's text, and every later write to the answer is fenced on it, so a
// retried attempt never appends to an earlier one's text.
export default Effect.gen(function* () {
    const sql = yield* SqlClient.SqlClient;
    yield* sql `ALTER TABLE messages ADD COLUMN attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0)`;
});
